import template from './lieferzeiten-statistics.html.twig';
import './lieferzeiten-statistics.scss';
import { normalizeTimelinePoints } from './timeline.util';

const TASK_CLOSABLE_STATUSES = ['open', 'in_progress', 'reopened'];
const TASK_REOPENABLE_STATUSES = ['done', 'cancelled'];

Shopware.Component.register('lieferzeiten-statistics', {
    template,

    inject: [
        'lieferzeitenOrdersService',
        'lieferzeitenTrackingService',
    ],

    mixins: ['notification'],

    props: {
        selectedDomain: {
            type: String,
            required: false,
            default: null,
        },
    },

    data() {
        return {
            periodOptions: [
                { value: 7, label: this.$t('lieferzeiten.statistics.period.7') },
                { value: 30, label: this.$t('lieferzeiten.statistics.period.30') },
                { value: 90, label: this.$t('lieferzeiten.statistics.period.90') },
                { value: 180, label: this.$t('lieferzeiten.statistics.period.180') },
                { value: 365, label: this.$t('lieferzeiten.statistics.period.365') },
                { value: 'custom', label: this.$t('lieferzeiten.statistics.period.custom') },
            ],
            selectedPeriod: 30,
            customFrom: null,
            customTo: null,
            selectedChannel: 'all',
            selectedActivity: null,
            isLoading: false,
            activitiesPage: 1,
            activitiesLimit: 25,
            activitiesTotal: 0,
            sortBy: 'eventAt',
            sortDirection: 'DESC',
            loadError: null,
            statistics: {
                metrics: {
                    openOrders: 0,
                    overdueShipping: 0,
                    overdueDelivery: 0,
                },
                channels: [],
                timeline: [],
                activitiesData: [],
                activities: {
                    total: 0,
                    page: 1,
                    limit: 25,
                },
            },
            tableColumns: [
                { property: 'orderNumber', label: this.$t('lieferzeiten.table.orderNumber'), primary: true },
                { property: 'domain', label: this.$t('lieferzeiten.table.domain') },
                { property: 'status', label: this.$t('lieferzeiten.table.status') },
                { property: 'eventAt', label: this.$t('lieferzeiten.statistics.activityDate') },
                { property: 'promisedAt', label: this.$t('lieferzeiten.statistics.promisedDate') },
                { property: 'actions', label: this.$t('lieferzeiten.statistics.actionsColumn') },
            ],
            actionLoadingByActivity: {},
        };
    },

    created() {
        this.loadStatistics();
    },

    watch: {
        selectedPeriod(value) {
            if (value !== 'custom') {
                this.customFrom = null;
                this.customTo = null;
            }

            this.activitiesPage = 1;
            this.loadStatistics();
        },
        selectedChannel() {
            this.activitiesPage = 1;
            this.loadStatistics();
        },
        customFrom() {
            if (this.selectedPeriod === 'custom') {
                this.activitiesPage = 1;
                this.loadStatistics();
            }
        },
        customTo() {
            if (this.selectedPeriod === 'custom') {
                this.activitiesPage = 1;
                this.loadStatistics();
            }
        },
        selectedDomain() {
            this.selectedChannel = 'all';
            this.activitiesPage = 1;
            this.loadStatistics();
        },
    },

    computed: {
        activitiesData() {
            return Array.isArray(this.statistics.activitiesData) ? this.statistics.activitiesData : [];
        },

        totalPages() {
            if (this.activitiesLimit <= 0) {
                return 1;
            }

            return Math.max(1, Math.ceil(this.activitiesTotal / this.activitiesLimit));
        },

        channelOptions() {
            return [
                { value: 'all', label: this.$t('lieferzeiten.statistics.allChannels') },
                ...this.statistics.channels.map((item) => ({ value: item.channel, label: item.channel })),
            ];
        },

        metrics() {
            return {
                open: this.statistics.metrics.openOrders,
                overdueShipping: this.statistics.metrics.overdueShipping,
                overdueDelivery: this.statistics.metrics.overdueDelivery,
            };
        },

        filteredOrders() {
            return this.activitiesData.map((activity) => ({
                ...activity,
                status: activity.status === 'open'
                    ? this.$t('lieferzeiten.status.open')
                    : (activity.status === 'done' ? this.$t('lieferzeiten.status.closed') : activity.status),
            }));
        },

        eventTypeBreakdown() {
            const totals = this.activitiesData.reduce((accumulator, activity) => {
                const normalizedEventType = String(activity?.eventType || 'unknown').trim().toLowerCase() || 'unknown';
                accumulator[normalizedEventType] = (accumulator[normalizedEventType] || 0) + 1;

                return accumulator;
            }, {});

            return Object.entries(totals)
                .map(([eventType, value]) => ({ eventType, value }))
                .sort((a, b) => b.value - a.value);
        },

        eventTypeBreakdownMaxValue() {
            if (!this.eventTypeBreakdown.length) {
                return 1;
            }

            return Math.max(...this.eventTypeBreakdown.map((item) => item.value));
        },

        criticalStatusBreakdown() {
            const totals = this.activitiesData.reduce((accumulator, activity) => {
                const statusKey = this.resolveCriticalStatus(activity);
                accumulator[statusKey] = (accumulator[statusKey] || 0) + 1;

                return accumulator;
            }, {});

            return Object.entries(totals)
                .map(([statusKey, value]) => ({ statusKey, value }))
                .sort((a, b) => b.value - a.value);
        },

        criticalStatusBreakdownMaxValue() {
            if (!this.criticalStatusBreakdown.length) {
                return 1;
            }

            return Math.max(...this.criticalStatusBreakdown.map((item) => item.value));
        },

        channelAnomalies() {
            const totals = this.activitiesData.reduce((accumulator, activity) => {
                const statusKey = this.resolveCriticalStatus(activity);

                if (statusKey === 'ok') {
                    return accumulator;
                }

                const sourceSystem = String(activity?.sourceSystem || 'unknown').trim() || 'unknown';

                if (!accumulator[sourceSystem]) {
                    accumulator[sourceSystem] = {
                        sourceSystem,
                        value: 0,
                        topStatus: statusKey,
                        statusTotals: {},
                    };
                }

                accumulator[sourceSystem].value += 1;
                accumulator[sourceSystem].statusTotals[statusKey] = (accumulator[sourceSystem].statusTotals[statusKey] || 0) + 1;

                const topStatusEntry = Object.entries(accumulator[sourceSystem].statusTotals)
                    .sort((a, b) => b[1] - a[1])[0];
                accumulator[sourceSystem].topStatus = topStatusEntry ? topStatusEntry[0] : 'ok';

                return accumulator;
            }, {});

            return Object.values(totals)
                .sort((a, b) => b.value - a.value)
                .slice(0, 5);
        },

        channelAnomaliesMaxValue() {
            if (!this.channelAnomalies.length) {
                return 1;
            }

            return Math.max(...this.channelAnomalies.map((item) => item.value));
        },

        channelChartData() {
            return this.statistics.channels;
        },

        maxChartValue() {
            if (!this.channelChartData.length) {
                return 1;
            }

            return Math.max(...this.channelChartData.map((item) => item.value));
        },

        timelineSeries() {
            return normalizeTimelinePoints(this.statistics.timeline, {
                selectedChannel: this.selectedChannel,
                selectedDomain: this.selectedDomain,
            });
        },

        timelineMaxValue() {
            if (!this.timelineSeries.length) {
                return 0;
            }

            return Math.max(...this.timelineSeries.map((item) => item.value));
        },

        timelineChartPaths() {
            if (this.timelineSeries.length < 2) {
                return null;
            }

            const width = 100;
            const height = 60;
            const maxValue = this.timelineMaxValue || 1;
            const step = width / (this.timelineSeries.length - 1);
            const points = this.timelineSeries.map((item, index) => {
                const x = Number((index * step).toFixed(2));
                const normalized = Math.min(item.value / maxValue, 1);
                const y = Number((height - (normalized * height)).toFixed(2));

                return { x, y };
            });

            const linePath = points
                .map((point, index) => `${index === 0 ? 'M' : 'L'} ${point.x} ${point.y}`)
                .join(' ');
            const areaPath = `${linePath} L ${width} ${height} L 0 ${height} Z`;

            return { linePath, areaPath };
        },
    },

    methods: {
        getAclService() {
            const injectedAcl = this.acl;

            if (typeof injectedAcl?.can === 'function') {
                return injectedAcl;
            }

            const serviceAcl = Shopware.Application.getContainer('service')?.acl;

            if (typeof serviceAcl?.can === 'function') {
                return serviceAcl;
            }

            return null;
        },

        hasViewAccess() {
            const aclService = this.getAclService();

            if (!aclService) {
                return false;
            }

            return aclService.can('lieferzeiten.viewer') || aclService.can('admin');
        },

        hasEditAccess() {
            const aclService = this.getAclService();

            if (!aclService) {
                return false;
            }

            return aclService.can('lieferzeiten.editor') || aclService.can('admin');
        },

        resolveActivityActions(item) {
            const actions = [];
            const eventType = String(item?.eventType || '').toLowerCase();

            if (['paket', 'position', 'audit'].includes(eventType)) {
                actions.push(this.createOrderAction(item));
            }

            if (eventType === 'task') {
                actions.push(this.createTaskRouteAction(item));
                actions.push(this.createTaskTransitionAction(item));
            }

            if (item?.trackingNumber) {
                actions.push(this.createTrackingAction(item));
            }

            if (actions.length === 0) {
                return [{
                    id: 'unavailable',
                    label: this.$t('lieferzeiten.statistics.actionsUnavailable'),
                    icon: 'regular-ban',
                    disabled: true,
                    disabledReason: this.$t('lieferzeiten.statistics.actionUnavailableReason'),
                    onClick: null,
                }];
            }

            return actions;
        },

        createOrderAction(item) {
            const hasOrderReference = Boolean(item?.paketId || item?.orderNumber);

            return {
                id: 'open-order',
                label: this.$t('lieferzeiten.statistics.actions.openOrder'),
                icon: 'regular-shopping-bag',
                disabled: !this.hasViewAccess() || !hasOrderReference,
                disabledReason: !this.hasViewAccess()
                    ? this.$t('lieferzeiten.statistics.actionReasons.noViewAcl')
                    : this.$t('lieferzeiten.statistics.actionReasons.missingOrderReference'),
                onClick: () => this.navigateToOrder(item),
            };
        },

        createTaskRouteAction(item) {
            return {
                id: 'open-task',
                label: this.$t('lieferzeiten.statistics.actions.openTask'),
                icon: 'regular-briefcase',
                disabled: !this.hasViewAccess() || !item?.taskId,
                disabledReason: !this.hasViewAccess()
                    ? this.$t('lieferzeiten.statistics.actionReasons.noViewAcl')
                    : this.$t('lieferzeiten.statistics.actionReasons.missingTaskReference'),
                onClick: () => this.navigateToTask(item),
            };
        },

        createTaskTransitionAction(item) {
            const normalizedStatus = String(item?.status || '').toLowerCase();
            const isClosable = TASK_CLOSABLE_STATUSES.includes(normalizedStatus);
            const isReopenable = TASK_REOPENABLE_STATUSES.includes(normalizedStatus);

            const operation = isReopenable ? 'reopen' : 'close';
            const isActionAvailable = isClosable || isReopenable;

            return {
                id: `task-${operation}`,
                label: this.$t(`lieferzeiten.statistics.actions.${operation}Task`),
                icon: isReopenable ? 'regular-redo' : 'regular-checkmark',
                disabled: !this.hasEditAccess() || !item?.taskId || !isActionAvailable,
                disabledReason: !this.hasEditAccess()
                    ? this.$t('lieferzeiten.statistics.actionReasons.noEditAcl')
                    : (!item?.taskId
                        ? this.$t('lieferzeiten.statistics.actionReasons.missingTaskReference')
                        : this.$t('lieferzeiten.statistics.actionReasons.unsupportedTaskStatus')),
                onClick: () => this.performTaskAction(item, operation),
                isLoading: Boolean(this.actionLoadingByActivity[this.getActionLoadingKey(item, operation)]),
            };
        },

        createTrackingAction(item) {
            return {
                id: 'open-tracking',
                label: this.$t('lieferzeiten.statistics.actions.openTracking'),
                icon: 'regular-shipping',
                disabled: !this.hasViewAccess() || !item?.trackingNumber,
                disabledReason: !this.hasViewAccess()
                    ? this.$t('lieferzeiten.statistics.actionReasons.noViewAcl')
                    : this.$t('lieferzeiten.statistics.actionReasons.missingTrackingReference'),
                onClick: () => this.navigateToTracking(item),
            };
        },

        getActionLoadingKey(item, operation) {
            return `${item?.id || 'unknown'}:${operation}`;
        },

        async performTaskAction(item, operation) {
            if (!item?.taskId || !['close', 'reopen'].includes(operation)) {
                return;
            }

            const loadingKey = this.getActionLoadingKey(item, operation);
            this.$set(this.actionLoadingByActivity, loadingKey, true);

            try {
                await this.lieferzeitenOrdersService.post(`tasks/${encodeURIComponent(item.taskId)}/${operation}`, {});
                this.createNotificationSuccess({
                    title: this.$t('lieferzeiten.statistics.actionSuccessTitle'),
                    message: this.$t(`lieferzeiten.statistics.actionSuccess.${operation}Task`),
                });
                await this.loadStatistics();
            } catch (error) {
                this.createNotificationError({
                    title: this.$t('lieferzeiten.statistics.actionErrorTitle'),
                    message: this.$t(`lieferzeiten.statistics.actionError.${operation}Task`),
                });
            } finally {
                this.$delete(this.actionLoadingByActivity, loadingKey);
            }
        },

        navigateToOrder(item) {
            this.$router.push({
                name: 'lieferzeiten.index',
                query: {
                    bestellnummer: item?.orderNumber || undefined,
                    paketId: item?.paketId || undefined,
                },
            });
        },

        navigateToTask(item) {
            this.$router.push({
                name: 'lieferzeiten.index',
                query: {
                    taskId: item?.taskId || undefined,
                    bestellnummer: item?.orderNumber || undefined,
                },
            });
        },

        async navigateToTracking(item) {
            const trackingNumber = String(item?.trackingNumber || '').trim();
            if (trackingNumber === '') {
                return;
            }

            try {
                await this.lieferzeitenTrackingService.history('dhl', trackingNumber);
            } catch (error) {
                this.createNotificationError({
                    title: this.$t('lieferzeiten.statistics.actionErrorTitle'),
                    message: this.$t('lieferzeiten.statistics.actionError.openTracking'),
                });
                return;
            }

            window.open(`https://www.dhl.de/de/privatkunden/pakete-empfangen/verfolgen.html?piececode=${encodeURIComponent(trackingNumber)}`, '_blank', 'noopener');
        },

        actionTooltip(action) {
            if (!action?.disabled) {
                return '';
            }

            return action.disabledReason || this.$t('lieferzeiten.statistics.actionUnavailableReason');
        },

        async loadStatistics() {
            this.isLoading = true;
            this.loadError = null;

            try {
                const useCustomRange = this.selectedPeriod === 'custom';
                const payload = await this.lieferzeitenOrdersService.getStatistics({
                    period: useCustomRange ? null : this.selectedPeriod,
                    from: useCustomRange && this.customFrom ? this.customFrom : null,
                    to: useCustomRange && this.customTo ? this.customTo : null,
                    domain: this.selectedDomain,
                    channel: this.selectedChannel,
                    page: this.activitiesPage,
                    limit: this.activitiesLimit,
                    sort: this.sortBy,
                    order: this.sortDirection,
                });

                this.statistics = {
                    metrics: payload.metrics ?? {
                        openOrders: 0,
                        overdueShipping: 0,
                        overdueDelivery: 0,
                    },
                    channels: Array.isArray(payload.channels) ? payload.channels : [],
                    timeline: Array.isArray(payload.timeline) ? payload.timeline : [],
                    activitiesData: Array.isArray(payload.activities?.data)
                        ? payload.activities.data
                        : (Array.isArray(payload.activitiesData) ? payload.activitiesData : []),
                    activities: {
                        total: Number(payload.activities?.total ?? payload.total ?? 0),
                        page: Number(payload.activities?.page ?? payload.page ?? this.activitiesPage),
                        limit: Number(payload.activities?.limit ?? payload.limit ?? this.activitiesLimit),
                    },
                };

                this.activitiesTotal = this.statistics.activities.total;
                this.activitiesPage = this.statistics.activities.page;
                this.activitiesLimit = this.statistics.activities.limit;
            } catch (error) {
                this.statistics = {
                    metrics: {
                        openOrders: 0,
                        overdueShipping: 0,
                        overdueDelivery: 0,
                    },
                    channels: [],
                    timeline: [],
                    activitiesData: [],
                    activities: {
                        total: 0,
                        page: 1,
                        limit: this.activitiesLimit,
                    },
                };
                this.activitiesTotal = 0;
                this.loadError = error;
            } finally {
                this.isLoading = false;
            }
        },

        onPageChange(page) {
            const nextPage = Number(page) || 1;
            this.activitiesPage = Math.max(1, Math.min(nextPage, this.totalPages));
            this.loadStatistics();
        },

        onSortChange({ dataIndex, direction }) {
            if (!dataIndex) {
                return;
            }

            this.sortBy = dataIndex;
            this.sortDirection = direction === 'ASC' ? 'ASC' : 'DESC';
            this.activitiesPage = 1;
            this.loadStatistics();
        },

        reloadActivityPage() {
            this.loadStatistics();
        },

        formatDate(dateString) {
            if (!dateString) {
                return '—';
            }

            return Shopware.Utils.format.date(dateString);
        },

        getChartBarWidth(value) {
            return `${Math.max(Math.round((value / this.maxChartValue) * 100), 6)}%`;
        },

        formatTimelineLabel(dateString) {
            return Shopware.Utils.format.date(dateString);
        },

        resolveCriticalStatus(activity) {
            const status = String(activity?.status || '').toLowerCase();
            const message = String(activity?.message || '').toLowerCase();
            const eventType = String(activity?.eventType || '').toLowerCase();
            const fullText = `${status} ${message} ${eventType}`;

            if (/(failed|error|dead[_\s-]?letter|exception)/.test(fullText)) {
                return 'failed';
            }

            if (/(overdue|late|ueberfaellig|überfällig|sla)/.test(fullText)) {
                return 'overdue';
            }

            if (/(queued|queue|pending|enqueued|scheduled|waiting)/.test(fullText)) {
                return 'queued';
            }

            if (/(retry|requeue|re-queue)/.test(fullText)) {
                return 'retrying';
            }

            if (/(timeout|timed\s*out)/.test(fullText)) {
                return 'timeout';
            }

            if (/(warning|warn|anomal)/.test(fullText)) {
                return 'warning';
            }

            return 'ok';
        },

        formatEventTypeLabel(eventType) {
            if (!eventType) {
                return 'Unknown';
            }

            return eventType
                .split(/[_\s-]+/)
                .filter(Boolean)
                .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
                .join(' ');
        },

        formatCriticalStatusLabel(statusKey) {
            const labels = {
                failed: 'Failed',
                queued: 'Queued',
                overdue: 'Overdue',
                retrying: 'Retrying',
                timeout: 'Timeout',
                warning: 'Warning',
                ok: 'OK',
            };

            return labels[statusKey] || this.formatEventTypeLabel(statusKey);
        },

        getBreakdownBarWidth(value, maxValue) {
            return `${Math.max(Math.round((value / (maxValue || 1)) * 100), 6)}%`;
        },

        onDrilldown(item) {
            this.selectedActivity = item;
        },

        closeDrilldown() {
            this.selectedActivity = null;
        },

        exportCsv() {
            const useCustomRange = this.selectedPeriod === 'custom';
            const query = new URLSearchParams();

            if (!useCustomRange) {
                query.set('period', String(this.selectedPeriod));
            }

            if (useCustomRange && this.customFrom) {
                query.set('from', this.customFrom);
            }

            if (useCustomRange && this.customTo) {
                query.set('to', this.customTo);
            }

            if (this.selectedDomain) {
                query.set('domain', this.selectedDomain);
            }

            if (this.selectedChannel) {
                query.set('channel', this.selectedChannel);
            }

            query.set('sort', this.sortBy);
            query.set('order', this.sortDirection);
            query.set('export', 'csv');

            const link = document.createElement('a');
            link.href = `${Shopware.Context.api.apiPath}/_action/lieferzeiten/v1/statistics?${query.toString()}`;
            link.target = '_blank';
            link.rel = 'noopener';
            link.click();
        },
    },
});
